    def release(self, e):
        self.keys.discard(e.keysym.lower())

    def tick(self):
        if self.state == "play":
            self.update()
        self.draw()
        self.root.after(16, self.tick)

    def update(self):
        if "left" in self.keys or "a" in self.keys:
            self.player[0] -= 5
        if "right" in self.keys or "d" in self.keys:
            self.player[0] += 5
